#include <iostream>
#include <vector>
#include <sstream>
using namespace std;

ListNode* parseList(string s) {
    if (s.empty() || s == "[]") return nullptr;
    stringstream ss(s);
    char ch;
    int val;
    ss >> ch; // '['
    ListNode* head = nullptr;
    ListNode* tail = nullptr;
    while (ss >> val) {
        ListNode* node = new ListNode(val);
        if (!head) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
        ss >> ch; // ',' or ']'
        if (ch == ']') break;
    }
    return head;
}

void printList(ListNode* head) {
    cout << "[";
    ListNode* curr = head;
    while (curr) {
        cout << curr->val;
        if (curr->next) cout << ",";
        curr = curr->next;
    }
    cout << "]" << endl;
}

int main() {
    string line;
    if (getline(cin, line)) {
        ListNode* head = parseList(line);
        Solution sol;
        ListNode* ans = sol.reverseList(head);
        printList(ans);
    }
    return 0;
}

